import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"第五部：行动与长期改变","description":"把一个真实问题交给九十天，用阶段门槛、证据链、节律与停止条件，让长期改变接受生活和时间的检验。","frontmatter":{"title":"第五部：行动与长期改变","description":"把一个真实问题交给九十天，用阶段门槛、证据链、节律与停止条件，让长期改变接受生活和时间的检验。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-5/long-term-action.md","filePath":"threads/part-5/long-term-action.md","lastUpdated":1795392000000}'),l={name:"threads/part-5/long-term-action.md"};function i(o,t,h,n,p,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第五部-行动与长期改变" tabindex="-1">第五部：行动与长期改变 <a class="header-anchor" href="#第五部-行动与长期改变" aria-label="Permalink to &quot;第五部：行动与长期改变&quot;">​</a></h1><p>走到这里，读者已经拥有很多可以开始的东西：一份基线、一个故事的新解释、一项可以交付的作品、一条在中断后能够回来的节律。</p><p>接下来最危险的动作，是把它们重新塞进一个过于宏大的愿望。我们很容易因为终于看见方向，就要求未来九十天每天完美；也容易在第三周第一次失速时，认定整个计划已经失败。</p><p>长期改变不是把热情延长。它是让同一个真实问题经过不同阶段、不同容量、反馈、遗忘和新场景之后，仍然能够被重新看见和调整。</p><p>这一部有三个核心章节。第一章把一个真实问题交给九十天；第二章用这本书自身展示方法怎样经过作品、失败、验证与公开发布；第三章处理第九十一天以后怎样关账、迁移、继续或停止。行动不只要离开书页，进入你的日历、作品、关系和生活；它还要在周期结束后完成交接，不靠下一次兴奋掩盖上一段经历。</p><h2 id="本部要回答的问题" tabindex="-1">本部要回答的问题 <a class="header-anchor" href="#本部要回答的问题" aria-label="Permalink to &quot;本部要回答的问题&quot;">​</a></h2><ul><li>九十天后，我要在什么真实场景完成什么，而不是笼统地“变得更好”？</li><li>进入下一阶段之前，必须看到什么证据？</li><li>每周只追踪哪个主问题，什么内容明确不补做？</li><li>身体、金钱、关系和责任出现变化时，怎样调整计划的重量？</li><li>什么结果意味着继续，什么意味着缩小、暂停或停止？</li></ul><p>一个没有停止条件的计划，很容易把沉没成本写成坚持。真正的承诺不仅说明要做什么，也说明不再用什么代价支付。</p><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>核心任务</th></tr></thead><tbody><tr><td>校准</td><td>第 1–14 天</td><td>保存基线，找到瓶颈，确认一个稳定入口</td></tr><tr><td>堆叠</td><td>第 15–56 天</td><td>形成可比较输出，获得反馈，改变一个变量</td></tr><tr><td>交付</td><td>第 57–90 天</td><td>更换听众、主题或环境，完成真实交付和迁移</td></tr><tr><td>交接</td><td>第 91 天以后</td><td>关账、迁移、修复或停止，让成果进入下一段生活</td></tr></tbody></table><p>先用<a href="./90-day-plan">行动篇：九十天，把生活交还给自己</a>把前三个阶段放进<a href="./../../templates/90-day-cycle">九十日行动总表</a>，再读<a href="./book-as-proof">案例篇：让这本书证明它的方法</a>，观察一套方法怎样在真实出版项目里经过结构重构、AI 协作、失败记录、自动验证和读者交接，最后用<a href="./after-90-days">九十天以后：把改变留在生活里</a>完成自己的关账与交接。总表管理方向和门槛，<a href="./../../templates/evidence-chain">证据链</a>解释结果，<a href="./../../templates/rhythm-ledger">节律账本</a>维护每周容量。不要让一张表承担所有工作，也不要让一个周期替你决定整个人生。</p><h2 id="读完留下什么" tabindex="-1">读完留下什么 <a class="header-anchor" href="#读完留下什么" aria-label="Permalink to &quot;读完留下什么&quot;">​</a></h2><p>九十天结束并完成交接之后，请留下三样能够继续服务生活的东西：</p><ol><li>一个真实受众已经看见、使用或评价过的作品；</li><li>一份仍然反复出现的错误地图；</li><li>一条不依赖理想状态也能回来的节律。</li></ol><p>如果方向已经不值得继续，停止也可以是合格的交付。写清楚依据、代价和已经完成的收尾，不让过去的投入替未来做决定。</p><h2 id="进入正文" tabindex="-1">进入正文 <a class="header-anchor" href="#进入正文" aria-label="Permalink to &quot;进入正文&quot;">​</a></h2><p>现在，请选择一件值得交给九十天、也值得在证据不足时放下的事。</p><p>不要先填满十二周。先写第一天的事实，第一周的问题，以及第十四天进入下一阶段之前必须看见的证据。</p>',18)])])}const f=a(l,[["render",i]]);export{m as __pageData,f as default};
